function WorkspaceMenu({ companyName, worker, busy, logout }: { companyName: string; worker: boolean; busy: boolean; logout: () => Promise<void> }) {
  const menu = useRef<HTMLDetailsElement>(null);
  const close = () => { if (menu.current) menu.current.open = false; };
  useEffect(() => {
    const outside = (event: PointerEvent) => { if (menu.current && !menu.current.contains(event.target as Node)) close(); };
    const escape = (event: KeyboardEvent) => { if (event.key === 'Escape' && menu.current?.open) { close(); menu.current.querySelector('summary')?.focus(); } };
    document.addEventListener('pointerdown', outside); document.addEventListener('keydown', escape);
    return () => { document.removeEventListener('pointerdown', outside); document.removeEventListener('keydown', escape); };
  }, []);
  return <details className="workspace-menu" ref={menu}><summary className="workspace-switch" aria-label="Open workspace menu"><span className="workspace-logo"><img src="/assets/soleil-logo.png" alt="" width="32" height="32" /></span><div><strong title={companyName}>{companyName}</strong><span>{worker ? 'Worker portal' : 'Business workspace'}</span></div><ChevronDown size={15} aria-hidden="true" /></summary><nav className="workspace-dropdown" aria-label="Workspace options"><div className="workspace-menu-label">{companyName}</div><Link to={worker ? '/app/portal' : '/app'} onClick={close}><LayoutDashboard size={16} />{worker ? 'My payments' : 'Workspace overview'}</Link>{!worker && <Link to="/app/company" onClick={close}><Building2 size={16} />Company details</Link>}<Link to="/app/settings" onClick={close}><Settings size={16} />Account settings</Link><button type="button" disabled={busy} onClick={() => { close(); void logout(); }}><LogOut size={16} />Switch account</button></nav></details>;
}

