function Status({ status }: { status: string }) { const icons: Record<string, LucideIcon> = { draft: FileText, approved: Check, committed: LockKeyhole, paid: CheckCheck }; const Icon = icons[status] || Clock3; return <Badge tone={status}><Icon size={12} />{humanize(status)}</Badge>; }
function PageHeader({ eyebrow, title, description, children }: { eyebrow?: string; title: string; description: string; children?: ReactNode }) { return <div className="page-heading"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1><p>{description}</p></div><div className="heading-actions">{children}</div></div>; }
function ErrorText({ message }: { message: string }) { return message ? <div className="form-error" role="alert"><AlertCircle size={16} />{message}</div> : null; }
