  const [session, updateSession] = useState<Session | null>(null), [config, updateConfig] = useState<PublicConfig | null>(null), [initializing, setInitializing] = useState(true), [error, setError] = useState('');
  const initialize = async () => { setInitializing(true); setError(''); try { const conf = await api<PublicConfig>('/api/config'); updateConfig(conf); try { const current = await api<Session>('/api/auth/session'); setSession(current); updateSession(current); } catch { setSession(null); updateSession(null); } } catch (e) { setError((e as Error).message); } finally { setInitializing(false); } };
  useEffect(() => { if (!isVerifier) void initialize(); }, [isVerifier]);
