  const worker = session.user.role === 'worker'; const nav = worker ? [{ path: '/app/portal', label: 'My payments', icon: Wallet }, { path: '/app/settings', label: 'Settings', icon: Settings }] : [{ path: '/app', label: 'Overview', icon: LayoutDashboard }, { path: '/app/invoices', label: 'Invoices', icon: FileText }, { path: '/app/workers', label: 'Contractors', icon: Users }, { path: '/app/treasury', label: 'Treasury', icon: Wallet }, { path: '/app/company', label: 'Company', icon: Building2 }, { path: '/app/activity', label: 'Activity', icon: ActivityIcon }, { path: '/app/testnet', label: 'Testnet lab', icon: FlaskConical }, { path: '/app/settings', label: 'Settings', icon: Settings }];
