  return <div className={`native-banner native-banner-${status}`} role={status === 'live' && !pending.length ? 'status' : 'alert'}><ShieldCheck size={18} /><div><strong>{setupRequired ? 'Native setup required' : status === 'live' ? 'Real Tempo testnet workspace' : 'Chain state needs a refresh'}</strong><span>{data.native?.network ?? 'Tempo Moderato'} · Test tokens have no economic value. {setupRequired ? 'Prepare the managed test wallets and native vault before creating payments.' : status === 'live' ? 'Balances and commitments are read from the native vault.' : 'Showing the last confirmed records; transaction actions are paused.'}</span>{setupRequired && data.user.role === 'owner' && <Link className="text-link" to="/app/settings">Prepare native vault in Settings <ArrowRight size={14} /></Link>}{(error || data.native?.warning) && <span className="native-warning">{error || data.native?.warning}</span>}{pending.length > 0 && <span className="native-warning">{pending.length} transaction{pending.length === 1 ? '' : 's'} awaiting reconciliation. Refresh to check authoritative chain state before retrying.</span>}</div><div className="native-freshness"><Badge tone={status === 'live' ? 'success' : 'warning'}>{setupRequired ? 'Setup required' : status === 'live' ? 'Chain synced' : humanize(status)}</Badge><span>{data.native?.checkedAt ? `Checked ${new Date(data.native.checkedAt).toLocaleTimeString()}` : 'Not yet verified'}</span>{data.native?.blockNumber && <span>Block {data.native.blockNumber}</span>}</div></div>;
