  const latestEvidence = commitments[0] ?? invoices.find(invoice => invoice.status === 'paid'); const vault = data.vaults.find(item => item.rail === worker.rail); const independent = native && latestEvidence ? verifierLink(vault?.address ?? '', latestEvidence.paymentId) : null;
  return <><PageHeader eyebrow="YOUR WORK. YOUR PAYMENT STORY." title={`Hi, ${data.user.name.split(' ')[0]}.`} description={`Your private payment portal with ${data.company.name}.`} /><div className="worker-welcome"><div><span className="hero-label"><ShieldCheck size={16} /> A PROMISE YOU CAN CHECK</span><h2>Know what’s funded.<br /><span>See what comes next.</span></h2><p>{native ? 'Committed principal is held on Tempo for your fixed receiving account. Claim a due invoice here, or verify and settle it independently.' : 'Your employer reserves committed principal for your fixed receiving account. Due payments can be claimed here in the local simulation.'}</p></div><Sun className="worker-welcome-sun" size={100} strokeWidth={1} /></div><section className="stats-grid worker-stats"><StatCard label="Your unpaid commitments" value={workspaceMoney(data, sumMoney(commitments.map(invoice => invoice.amount)), worker.rail)} description={`${commitments.length} funded invoice${commitments.length === 1 ? '' : 's'} ${native ? `in ${assetLabel(data, worker.rail)}` : 'in this simulation'}`} icon={LockKeyhole} accent /><StatCard label={native ? "Test wallet balance" : "Payments received"} value={workspaceMoney(data, worker.received, worker.rail)} description={native ? `Current ${assetLabel(data, worker.rail)} balance on Tempo` : 'Delivered demo payment assets'} icon={CheckCheck} /><StatCard label="Invoices awaiting payment" value={String(invoices.filter(invoice => invoice.status !== 'paid').length)} description="Includes uncommitted invoices" icon={FileText} /></section><section className="panel recipient-panel"><div className="panel-heading"><div><h2>Your receiving account</h2><p>Check the destination before any commitment is created.</p></div><Badge tone={worker.blocked ? 'warning' : worker.confirmed ? 'success' : 'neutral'}>{worker.blocked ? 'Transfer restricted' : worker.confirmed ? native ? 'Test wallet confirmed' : 'Confirmed in demo' : 'Confirmation required'}</Badge></div><div className="recipient-details"><RailBadge rail={worker.rail} /><code>{worker.address}</code><button className="icon-button" aria-label="Copy receiving account" onClick={() => void navigator.clipboard.writeText(worker.address).then(() => notify('Receiving account copied.')).catch(() => notify('Clipboard unavailable.', 'error'))}><Copy size={16} /></button>{!worker.confirmed && <Button disabled={!!busy || nativeBlocked(data) || (native && !worker.managedTestWallet)} title={native && !worker.managedTestWallet ? 'External wallet proof is not supported in this presentation flow.' : undefined} icon={Check} onClick={() => void mutate(`/api/workers/${worker.id}/confirm`).catch(() => undefined)}>{busy.endsWith(`/workers/${worker.id}/confirm`) ? <><Spinner />Confirming…</> : native ? 'Confirm managed test recipient' : 'Confirm demo recipient'}</Button>}</div><p className="recipient-disclosure">{native ? worker.managedTestWallet ? 'This is your assigned managed presentation wallet. Confirmation records an ECDSA signature from that test wallet; it does not prove ownership of a personal wallet. Settlement is submitted by a separate funded test caller and can only deliver to the fixed recipient.' : 'This external address requires a signed wallet proof before commitment. External wallet signing is not supported in the managed presentation flow.' : 'This confirmation is simulated. It is not a signed proof of real wallet control. Contact the company before funding if the account or rail is wrong.'}</p>{native && worker.confirmationProof && <details className="confirmation-proof"><summary>Recorded test-wallet signature</summary><code>{worker.confirmationProof}</code></details>}</section><section className="panel"><div className="panel-heading"><div><h2>Your invoices</h2><p>Only your assigned invoices are visible in this portal.</p></div><Badge tone="neutral"><LockKeyhole size={12} />Private view</Badge></div><InvoiceTable invoices={invoices} /></section><section className="panel independent-panel"><span className="readiness-icon"><ShieldCheck size={22} /></span><div><h2>A receipt that travels with you</h2><p>{native ? 'Your native receipt contains the fixed beneficiary, amount, due time, vault, payment ID and transaction trail. The public verifier checks the contract and reads the commitment directly from Tempo, without workspace access.' : 'Export a funded or paid invoice’s receipt to inspect its recipient, amount, due time and simulation reference. Demo receipts cannot prove chain funding.'}</p><div className="independent-actions">{latestEvidence && <Button variant="secondary" icon={Download} onClick={() => open({ kind: 'receipt', invoice: latestEvidence })}>Open commitment receipt</Button>}<Link to={independent ?? '/verify'} className="text-link">{native ? 'Verify and claim independently' : 'Separate native testnet verifier'}<ArrowUpRight size={16} /></Link></div><p className="fine-print">{native ? 'Native testnet assets have no economic value. Claim status is checked against actual chain state.' : 'The verifier reads real testnet commitments. These local demo invoices cannot be verified there.'}</p></div></section></>;
