  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setError(''); try { const form = new FormData(event.currentTarget); await mutate('/api/workers', native ? { name: form.get('name'), email: form.get('email'), rail: 'tempo' } : Object.fromEntries(form)); close(); } catch (e) { setError((e as Error).message); } };
