function TreasuryDialog({ vault: initialVault, action, close }: { vault?: Vault; action: string; close: () => void }) { const { data, mutate, busy } = useWorkspace(); const [vaultId, setVaultId] = useState(initialVault?.id || data.vaults.find(v => !v.retired)?.id || ''), [error, setError] = useState(''); const vault = data.vaults.find(v => v.id === vaultId); const labels: Record<string, string> = { deposit: 'Add demo funds', withdraw: 'Withdraw surplus', allocate: 'Allocate demo surplus', loss: 'Simulate strategy loss', recover: 'Recover strategy value' }; const detail: Record<string, string> = { deposit: 'Adds simulated funds to this native vault. No bank deposit, wallet transfer, or real money movement occurs.', withdraw: 'Only unreserved funds can leave the simulated vault. Contractor principal remains protected.', allocate: 'Moves simulated surplus into a risk adapter. Strategy value cannot fund new commitments.', loss: 'Reduces the simulated strategy value. Existing liquid contractor reserves are unchanged.', recover: 'Returns available strategy value to the simulated vault. It does not create real funds.' }; const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setError(''); try { const amount = parseMoney(String(new FormData(event.currentTarget).get('amount'))); await mutate(`/api/vaults/${vaultId}/${['loss', 'recover'].includes(action) ? 'simulate' : action}`, ['loss', 'recover'].includes(action) ? { event: action, amount } : { amount }); close(); } catch (e) { setError((e as Error).message); } }; return <Dialog title={labels[action]} close={close}><div className="dialog-simulation"><FlaskConical size={16} /> Local simulation only</div><p className="modal-intro">{detail[action]}</p><form className="form-stack" onSubmit={submit}><label>Native vault<select value={vaultId} onChange={e => setVaultId(e.target.value)} disabled={!!initialVault} aria-label="Native vault">{data.vaults.map(v => <option key={v.id} value={v.id}>{humanize(v.rail)} · {v.asset}{v.retired ? ' · retired' : ''}</option>)}</select></label>{vault && <div className="treasury-modal-stats"><span>Liquid<strong>{formatMoney(vault.balance)}</strong></span><span>Committed<strong>{formatMoney(vault.committed)}</strong></span><span>Available surplus<strong>{formatMoney(vault.surplus)}</strong></span></div>}<label>Amount<input name="amount" inputMode="decimal" required placeholder="0.00" /></label><ErrorText message={error} /><div className="modal-actions"><Button variant="secondary" type="button" onClick={close}>Cancel</Button><Button type="submit" disabled={!!busy || !vault}>{busy && <Spinner />}{labels[action]}</Button></div></form></Dialog>; }
function ReceiptDialog({ invoice, close }: { invoice: Invoice; close: () => void }) {
  const [receipt, setReceipt] = useState<Receipt | null>(null), [error, setError] = useState(''), [loading, setLoading] = useState(false); const { notify, data } = useWorkspace();
  const load = async () => { setLoading(true); setError(''); try { setReceipt(await api<Receipt>(`/api/receipts/${invoice.id}`)); } catch (e) { setError((e as Error).message); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, [invoice.id, data.native?.blockNumber]);
  const native = receipt?.mode === 'testnet'; const publicLink = native && receipt ? verifierLink(receipt.vault, receipt.paymentId) : null;
  return <Dialog title={`Receipt · ${invoice.number}`} close={close}><ErrorText message={error} />{!receipt && loading && <div className="receipt-loading"><Spinner />Reading your receipt…</div>}{receipt && <><div className="receipt-status"><ShieldCheck size={26} /><div><h3>{humanize(receipt.status)}</h3><p>{formatMoney(receipt.amount, receipt.decimals, native ? '' : '$')} · {receipt.asset}</p></div><RailBadge rail={receipt.rail} /></div>{native && <div className="native-receipt-label"><Badge tone={error ? 'warning' : 'success'}>{error ? 'Last recorded state' : 'Native chain receipt'}</Badge><span>Tempo Moderato · Chain {receipt.chainId ?? 42431}</span></div>}<dl className="receipt-fields"><div><dt>Payment ID</dt><dd>{receipt.paymentId}</dd></div><div><dt>Fixed recipient</dt><dd>{native && addressLink(receipt.recipient) ? <a href={addressLink(receipt.recipient)!} target="_blank" rel="noopener noreferrer">{receipt.recipient}<ExternalLink size={13} /></a> : receipt.recipient}</dd></div><div><dt>Native vault</dt><dd>{native && addressLink(receipt.vault) ? <a href={addressLink(receipt.vault)!} target="_blank" rel="noopener noreferrer">{receipt.vault}<ExternalLink size={13} /></a> : receipt.vault}</dd></div><div><dt>Due time</dt><dd>{new Date(receipt.dueAt).toLocaleString()}</dd></div>{native && <div><dt>Commitment transaction</dt><dd>{transactionLink(receipt.commitTransactionRef) ? <a href={transactionLink(receipt.commitTransactionRef)!} target="_blank" rel="noopener noreferrer">{receipt.commitTransactionRef}<ExternalLink size={13} /></a> : 'Confirmation reference unavailable'}</dd></div>}<div><dt>{native ? 'Settlement transaction' : 'Transaction reference'}</dt><dd>{native && transactionLink(receipt.transactionRef) ? <a href={transactionLink(receipt.transactionRef)!} target="_blank" rel="noopener noreferrer">{receipt.transactionRef}<ExternalLink size={13} /></a> : receipt.transactionRef || 'Not yet settled'}</dd></div>{native && receipt.checkedAt && <div><dt>Last chain check</dt><dd>{new Date(receipt.checkedAt).toLocaleString()}</dd></div>}<div><dt>Mode / version</dt><dd>{receipt.mode} / {receipt.version}</dd></div></dl><div className="info-box">{native ? <ShieldCheck size={18} /> : <FlaskConical size={18} />}<p>{receipt.statement}</p></div><p className="fine-print">{native ? 'Test tokens have no economic value. Open the public verifier to read the fixed-recipient commitment independently of this workspace.' : 'Simulation references are not explorer links or evidence of on-chain funding.'}</p><div className="modal-actions"><Button variant="secondary" icon={Copy} onClick={() => void navigator.clipboard.writeText(JSON.stringify(receipt, null, 2)).then(() => notify('Receipt copied.')).catch(() => notify('Clipboard unavailable. Use Download JSON.', 'error'))}>Copy receipt</Button><Button icon={Download} onClick={() => downloadData(JSON.stringify(receipt, null, 2), `soleil-${invoice.number}-receipt.json`, 'application/json')}>Download JSON</Button></div>{native && <Button className="receipt-refresh" variant="ghost" icon={RefreshCw} disabled={loading} onClick={() => void load()}>{loading ? 'Reading chain…' : 'Refresh receipt'}</Button>}<Link to={publicLink ?? '/verify'} className="text-link receipt-verifier" onClick={close}>{publicLink ? 'Verify and claim this commitment independently' : 'Open separate native testnet verifier'}<ArrowUpRight size={15} /></Link>{!native && <p className="fine-print">This local receipt cannot be checked in the native testnet tool.</p>}</>}</Dialog>;
}
function FormationDialog({ provider, close }: { provider: 'stablecorp' | 'atlas'; close: () => void }) { const [consent, setConsent] = useState(false), [busy, setBusy] = useState(false), [error, setError] = useState(''), [handoff, setHandoff] = useState<{ url: string; statement: string } | null>(null); const { refresh } = useWorkspace(); const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { setHandoff(await api('/api/company/formation', { method: 'POST', body: { provider } })); await refresh(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }; return <Dialog title={`Explore ${provider === 'atlas' ? 'Stripe Atlas' : 'Stablecorp'}`} close={close}><p className="modal-intro">Open the provider’s own formation workflow. Review their fees, terms and eligibility directly.</p><div className="info-box"><Building2 size={18} /><p>This handoff does not incorporate a company, approve KYB, or open an account. Soleil does not submit identity documents or formation applications on your behalf.</p></div>{handoff ? <><div className="handoff-ready"><CheckCircle2 size={22} /><h3>Your provider handoff is ready</h3><p>{handoff.statement}</p></div><a className="button button-primary full-width" href={handoff.url} target="_blank" rel="noopener noreferrer">Open provider website <ExternalLink size={16} /></a><p className="fine-print">Your business readiness status remains separate from this link.</p></> : <form className="form-stack" onSubmit={submit}><label className="checkbox-label"><input type="checkbox" checked={consent} onChange={e => setConsent(e.target.checked)} required /><span>I understand this is a hosted referral, and I will review the provider’s requirements and terms.</span></label><ErrorText message={error} /><div className="modal-actions"><Button type="button" variant="secondary" onClick={close}>Cancel</Button><Button disabled={!consent || busy} type="submit">{busy && <Spinner />}Prepare provider link<ArrowUpRight size={16} /></Button></div></form>}</Dialog>; }
function InviteDialog({ worker, close }: { worker: Worker; close: () => void }) { const [result, setResult] = useState<{ url: string } | null>(null), [error, setError] = useState(''), [busy, setBusy] = useState(false); const { notify } = useWorkspace(); const generate = async () => { setBusy(true); setError(''); try { setResult(await api(`/api/workers/${worker.id}/invitation`, { method: 'POST', body: {} })); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }; return <Dialog title={`Invite ${worker.name}`} close={close}><p className="modal-intro">Generate a private, expiring, single-use signup link for {worker.email}. Share it with the contractor yourself. Soleil does not send email.</p><ErrorText message={error} />{result ? <><label className="form-stack">Private invitation link<input readOnly value={new URL(result.url, window.location.origin).href} onFocus={e => e.target.select()} /></label><div className="info-box"><LockKeyhole size={17} /><p>Anyone with this link can complete this contractor’s signup. Send it only to the intended person.</p></div><div className="modal-actions"><Button variant="secondary" onClick={close}>Done</Button><Button icon={Copy} onClick={() => void navigator.clipboard.writeText(new URL(result.url, window.location.origin).href).then(() => notify('Invitation link copied.')).catch(() => setError('Clipboard unavailable. Select and copy the invitation field.'))}>Copy invitation link</Button></div></> : <div className="modal-actions"><Button variant="secondary" onClick={close}>Cancel</Button><Button disabled={busy} icon={Mail} onClick={() => void generate()}>{busy && <Spinner />}Generate private link</Button></div>}</Dialog>; }
function ConfirmDialog({ modal, close }: { modal: NonNullable<ModalState>; close: () => void }) { const { data, mutate, busy } = useWorkspace(); const [error, setError] = useState(''); const chainAction = !!modal.path && /\/invoices\/[^/]+\/(commit|pay)$|\/vaults\//.test(modal.path); const submit = async () => { if (!modal.path) return; setError(''); try { await mutate(modal.path, modal.body); close(); } catch (e) { setError((e as Error).message); } }; return <Dialog title={modal.title || 'Confirm action'} close={close}><p className="modal-intro">{modal.description}</p><div className={isNative(data) ? 'dialog-native' : 'dialog-simulation'}>{isNative(data) ? <ShieldCheck size={16} /> : <FlaskConical size={16} />}{isNative(data) ? 'Real Tempo transaction · Managed test wallet · Test assets only' : 'This changes the local demonstration only.'}</div><ErrorText message={error} /><div className="modal-actions"><Button variant="secondary" onClick={close}>Cancel</Button><Button disabled={!!busy || (chainAction && nativeBlocked(data))} onClick={() => void submit()}>{busy && <Spinner />}{busy && isNative(data) ? 'Waiting for confirmation…' : 'Confirm'}</Button></div></Dialog>; }









